184:     /**
185:      * @notice Floods the field, up to 0.1% of the total Bean supply worth of pods.
186:      */
187:     function floodPodline() private {
188:         AppStorage storage s = LibAppStorage.diamondStorage();
189:         // Make 0.1% of the total bean supply worth of pods harvestable.
190: 
191:         uint256 totalBeanSupply = C.bean().totalSupply();
192:         uint256 sopFieldBeans = totalBeanSupply.div(FLOOD_PODLINE_PERCENT_DENOMINATOR); // 1/1000 = 0.1% of total supply
193: 
194:         // Note there may be cases where zero harvestable pods are available. For clarity, the code will still emit an event
195:         // but with zero sop field beans.
196:         uint256 maxHarvestable = s.sys.fields[s.sys.activeField].pods.sub(
197:             s.sys.fields[s.sys.activeField].harvestable
198:         );
199: 
200:         sopFieldBeans = sopFieldBeans > maxHarvestable ? maxHarvestable : sopFieldBeans;
201: 
202:         s.sys.fields[s.sys.activeField].harvestable = s
203:             .sys
204:             .fields[s.sys.activeField]
205:             .harvestable
206:             .add(sopFieldBeans);
207:         C.bean().mint(address(this), sopFieldBeans);
208: 
209:         emit SeasonOfPlentyField(sopFieldBeans);
210:     }
