212:     function getWellsByDeltaB()
213:         internal
214:         view
215:         returns (
216:             WellDeltaB[] memory wellDeltaBs,
217:             uint256 totalPositiveDeltaB,
218:             uint256 totalNegativeDeltaB,
219:             uint256 positiveDeltaBCount
220:         )
221:     {
222:         address[] memory wells = LibWhitelistedTokens.getCurrentlySoppableWellLpTokens();
223:         wellDeltaBs = new WellDeltaB[](wells.length);
224: 
225:         for (uint i = 0; i < wells.length; i++) {
226:             wellDeltaBs[i] = WellDeltaB(wells[i], LibDeltaB.currentDeltaB(wells[i]));
227:             if (wellDeltaBs[i].deltaB > 0) {
228:                 totalPositiveDeltaB += uint256(wellDeltaBs[i].deltaB);
229:                 positiveDeltaBCount++;
230:             } else {
231:                 totalNegativeDeltaB += uint256(-wellDeltaBs[i].deltaB);
232:             }
233:         }
234: 
235:         // Sort the wellDeltaBs array
236:         quickSort(wellDeltaBs, 0, int(wellDeltaBs.length - 1));
237:     }
