239:     // Reviewer note: This works, but there's got to be a way to make this more gas efficient
240:     function quickSort(
241:         WellDeltaB[] memory arr,
242:         int left,
243:         int right
244:     ) internal pure returns (WellDeltaB[] memory) {
245:         if (left >= right) return arr;
246: 
247:         // Choose the median of left, right, and middle as pivot (improves performance on random data)
248:         uint mid = uint(left) + (uint(right) - uint(left)) / 2;
249:         WellDeltaB memory pivot = arr[uint(left)].deltaB > arr[uint(mid)].deltaB
250:             ? (
251:                 arr[uint(left)].deltaB < arr[uint(right)].deltaB
252:                     ? arr[uint(left)]
253:                     : arr[uint(right)]
254:             )
255:             : (arr[uint(mid)].deltaB < arr[uint(right)].deltaB ? arr[uint(mid)] : arr[uint(right)]);
256: 
257:         int i = left;
258:         int j = right;
259:         while (i <= j) {
260:             while (arr[uint(i)].deltaB > pivot.deltaB) i++;
261:             while (pivot.deltaB > arr[uint(j)].deltaB) j--;
262:             if (i <= j) {
263:                 (arr[uint(i)], arr[uint(j)]) = (arr[uint(j)], arr[uint(i)]);
264:                 i++;
265:                 j--;
266:             }
267:         }
268: 
269:         if (left < j) {
270:             return quickSort(arr, left, j);
271:         }
272:         if (i < right) {
273:             return quickSort(arr, i, right);
274:         }
275:         return arr;
276:     }
