278:     /**
279:      * @dev Flood was previously called a "Season of Plenty" (SOP for short).
280:      * When Beanstalk has been Oversaturated for a Season, Beanstalk returns the
281:      * Bean price to its peg by minting additional Beans and selling them directly
282:      * on the sop well. Proceeds from the sale in the form of WETH are distributed to
283:      * Stalkholders at the beginning of a Season in proportion to their Stalk
284:      * ownership when the Farm became Oversaturated. Also, at the beginning of the
285:      * Flood, all Pods that were minted before the Farm became Oversaturated Ripen
286:      * and become Harvestable.
287:      * For more information On Oversaturation see {Weather.handleRain}.
288:      */
289:     function sopWell(WellDeltaB memory wellDeltaB) private {
290:         AppStorage storage s = LibAppStorage.diamondStorage();
291:         if (wellDeltaB.deltaB > 0) {
292:             IERC20 sopToken = LibWell.getNonBeanTokenFromWell(wellDeltaB.well);
293: 
294:             uint256 sopBeans = uint256(wellDeltaB.deltaB);
295:             C.bean().mint(address(this), sopBeans);
296: 
297:             // Approve and Swap Beans for the non-bean token of the SOP well.
298:             C.bean().approve(wellDeltaB.well, sopBeans);
299:             uint256 amountOut = IWell(wellDeltaB.well).swapFrom(
300:                 C.bean(),
301:                 sopToken,
302:                 sopBeans,
303:                 0,
304:                 address(this),
305:                 type(uint256).max
306:             );
307:             rewardSop(wellDeltaB.well, amountOut, address(sopToken));
308:             emit SeasonOfPlentyWell(
309:                 s.sys.season.current,
310:                 wellDeltaB.well,
311:                 address(sopToken),
312:                 amountOut
313:             );
314:         }
315:     }
