317:     /**
318:      * @dev Allocate `sop token` during a Season of Plenty.
319:      */
320:     function rewardSop(address well, uint256 amount, address sopToken) private {
321:         AppStorage storage s = LibAppStorage.diamondStorage();
322:         s.sys.sop.sops[s.sys.season.rainStart][well] = s
323:         .sys
324:         .sop
325:         .sops[s.sys.season.lastSop][well].add(amount.mul(C.SOP_PRECISION).div(s.sys.rain.roots));
326: 
327:         s.sys.season.lastSop = s.sys.season.rainStart;
328:         s.sys.season.lastSopSeason = s.sys.season.current;
329: 
330:         // update Beanstalk's stored overall plenty for this well
331:         s.sys.sop.plentyPerSopToken[sopToken] += amount;
332:     }
